files.content:
.tab:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.tabs{
  position:relative;
  display:flex;
  border-bottom:var(--bw-1) solid var(--obsidian-800);
  padding:0 var(--s-4);
}
.tab{
  background:none;
  border:0;
  cursor:pointer;
  padding:var(--s-3) var(--s-4);
  font-family:var(--font-sans);
  font-size:var(--t-small);
  font-weight:500;
  color:var(--obsidian-300);
  transition:color var(--d-quick) var(--ease-standard);
  position:relative;
  z-index:1;
}
.tab:hover{
  color:var(--obsidian-100);
}
.tab:active{
  color:var(--obsidian-300);
}
.tab.active{
  color:var(--obsidian-100);
  font-weight:600;
}
.tab-indicator{
  position:absolute;
  left:0;
  bottom:calc(-1 * var(--s-px));
  height:2px;
  width:0;
  background:var(--primary-500);
  transition:transform var(--d-base) var(--ease-decel), width var(--d-base) var(--ease-decel);
  pointer-events:none;
  will-change:transform,width;
}
.tab-panels{
  position:relative;
}
.tab-panel{
  display:none;
  padding:var(--s-6);
  color:var(--obsidian-300);
  font-size:var(--t-small);
  line-height:1.7;
  opacity:0;
  transform:translateY(6px);
  transition:opacity var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-standard);
}
.tab-panel.active{
  display:block;
}
@media (prefers-reduced-motion: reduce){
  .tab-indicator{
    transition:none;
  }
  .tab-panel{
    transition:none;
    opacity:1;
    transform:none;
  }
}
@media (max-width: 900px){
  .tabs{
    overflow-x:auto;
    scrollbar-width:none;
  }
  .tabs::-webkit-scrollbar{
    display:none;
  }
  .tab{
    white-space:nowrap;
  }
}
.tabs){
  width:min(100%, calc(var(--s-32) * 2.5));
}
